{
  "implementation": "def solve(case):
    lines = case.get("lines", [])
    trajectory = []
    for line in lines:
        line = line.strip()
        if ": " in line:
            typ, content = line.split(": ", 1)
        else:
            typ = line
            content = ""
        trajectory.append({"type": typ.strip(), "content": content.strip()})
    valid = True
    error_line = None
    valid_types = {"Thought", "Action", "Observation", "Final"}
    if not trajectory:
        valid = False
        error_line = None
    else:
        # check each entry type is valid
        for i, entry in enumerate(trajectory):
            if entry["type"] not in valid_types:
                valid = False
                error_line = i
                break
        if valid:
            if trajectory[0]["type"] != "Thought":
                valid = False
                error_line = 0
            else:
                allowed_next = {
                    "Thought": ["Action", "Final"],
                    "Action": ["Observation"],
                    "Observation": ["Thought", "Final"],
                    "Final": []
                }
                for i in range(1, len(trajectory)):
                    prev_type = trajectory[i-1]["type"]
                    cur_type = trajectory[i]["type"]
                    if cur_type not in allowed_next.get(prev_type, []):
                        valid = False
                        error_line = i
                        break
        if valid and trajectory[-1]["type"] != "Final":
            valid = False
            error_line = len(trajectory) - 1
    return {
        "valid": valid,
        "error_line": error_line,
        "trajectory": trajectory
    }"
}
